// CONFIDENCE: HIGH for the normal path. Read in full (26 lines). |Divisor| <= 1e-8 returns 0.
// Result is the truncated remainder Value - trunc(Value / Divisor) * Divisor, clamped to [-|Divisor|, |Divisor|].
float FMath_Fmod(float Value, float Divisor)
{
	if (FMath::Abs(Divisor) <= 1e-8f) return 0.0f;
	float Quot = Value / Divisor;
	if (FMath::Abs(Quot) < 8388608.0f) Quot = static_cast<float>(static_cast<int32>(Quot));
	float Prod = Quot * Divisor;
	if (FMath::Abs(Value) < FMath::Abs(Prod)) Prod = Value;
	const float Rem = Value - Prod;
	if (-FMath::Abs(Divisor) <= Rem) return FMath::Min(Rem, FMath::Abs(Divisor));
	return -FMath::Abs(Divisor);
}
